     1	package io.github.julianperge.modular_planters.multiblock;
     2	
     3	import io.github.julianperge.modular_planters.blockentity.ExportBlockEntity;
     4	import net.minecraft.world.item.ItemStack;
     5	import net.neoforged.neoforge.transfer.CombinedResourceHandler;
     6	import net.neoforged.neoforge.transfer.DelegatingResourceHandler;
     7	import net.neoforged.neoforge.transfer.ResourceHandler;
     8	import net.neoforged.neoforge.transfer.ResourceHandlerUtil;
     9	import net.neoforged.neoforge.transfer.item.ItemResource;
    10	import net.neoforged.neoforge.transfer.item.ItemStacksResourceHandler;
    11	import net.neoforged.neoforge.transfer.transaction.Transaction;
    12	import net.neoforged.neoforge.transfer.transaction.TransactionContext;
    13	import org.jspecify.annotations.Nullable;
    14	
    15	import java.util.List;
    16	
    17	public final class OutputSink {
    18	    private final List<ExportBlockEntity> blocks;
    19	    private final @Nullable MeLink me;
    20	    private final Runnable onStale;
    21	    private final ResourceHandler<ItemResource> allBlocks;
    22	    private final ResourceHandler<ItemResource> extractView = new DelegatingResourceHandler<>(this::liveHandler);
    23	
    24	    public OutputSink(List<ExportBlockEntity> inOrder, @Nullable MeLink me, Runnable onStale) {
    25	        this.blocks = List.copyOf(inOrder);
    26	        this.me = me;
    27	        this.onStale = onStale;
    28	        this.allBlocks = new CombinedResourceHandler<>(blocks.stream().map(ExportBlockEntity::externalHandler).toList());
    29	    }
    30	
    31	    private List<ExportBlockEntity> live() {
    32	        return LiveBlocks.of(blocks, onStale);
    33	    }
    34	
    35	    boolean allLive() {
    36	        return LiveBlocks.allLive(blocks, onStale);
    37	    }
    38	
    39	    // A combined handler fixes its slot count when it is built, so a removed block needs a new one until the core rebuilds the pool.
    40	    private ResourceHandler<ItemResource> liveHandler() {
    41	        return allLive() ? allBlocks
    42	                : new CombinedResourceHandler<>(live().stream().map(ExportBlockEntity::externalHandler).toList());
    43	    }
    44	
    45	    private @Nullable MeLink liveMe() {
    46	        if (me == null) {
    47	            return null;
    48	        }
    49	        if (me.isRemoved()) {
    50	            onStale.run();
    51	            return null;
    52	        }
    53	        return me;
    54	    }
    55	
    56	    public boolean hasRoomFor(List<ItemStack> stacks) {
    57	        try (Transaction tx = Transaction.openRoot()) {
    58	            // ME has no transactions, so stacks that share ME room can both pass, and the part ME refuses later goes to the export blocks or is held in the planter block.
    59	            for (ItemStack stack : stacks) {
    60	                if (!insertInto(stack, tx).isEmpty()) {
    61	                    return false;
    62	                }
    63	            }
    64	            return true;
    65	        }
    66	    }
    67	
    68	    public ItemStack insert(ItemStack stack) {
    69	        return insertInto(stack, null);
    70	    }
    71	
    72	    public ResourceHandler<ItemResource> extractView() {
    73	        return extractView;
    74	    }
    75	
    76	    // ME cannot join a transaction, so each slot gives up the items inside one, offers them to ME, takes back whatever ME refused, and only then commits, which keeps items from being copied or lost.
    77	    public void moveExportsInto(MeLink me) {
    78	        if (!me.online()) {
    79	            return;
    80	        }
    81	        for (ExportBlockEntity block : live()) {
    82	            ItemStacksResourceHandler storage = block.storage();
    83	            for (int slot = 0; slot < storage.size(); slot++) {
    84	                ItemResource resource = storage.getResource(slot);
    85	                if (resource.isEmpty()) {
    86	                    continue;
    87	                }
    88	                int asked = (int) me.insertItem(resource, storage.getAmountAsInt(slot), true);
    89	                if (asked == 0) {
    90	                    continue;
    91	                }
    92	                try (Transaction tx = Transaction.openRoot()) {
    93	                    int taken = storage.extract(slot, resource, asked, tx);
    94	                    int accepted = (int) me.insertItem(resource, taken, false);
    95	                    storage.insert(slot, resource, taken - accepted, tx);
    96	                    tx.commit();
    97	                }
    98	            }
    99	        }
   100	    }
   101	
   102	    public int fillPercent() {
   103	        long stored = 0;
   104	        long capacity = 0;
   105	        for (ExportBlockEntity block : live()) {
   106	            ItemStacksResourceHandler storage = block.storage();
   107	            for (int slot = 0; slot < storage.size(); slot++) {
   108	                stored += storage.getAmountAsLong(slot);
   109	                capacity += storage.getCapacityAsLong(slot, storage.getResource(slot));
   110	            }
   111	        }
   112	        return capacity == 0 ? 0 : (int) (stored * 100 / capacity);
   113	    }
   114	
   115	    private ItemStack insertInto(ItemStack stack, @Nullable TransactionContext transaction) {
   116	        if (stack.isEmpty()) {
   117	            return ItemStack.EMPTY;
   118	        }
   119	        ItemResource resource = ItemResource.of(stack);
   120	        int remaining = stack.getCount();
   121	        MeLink link = liveMe();
   122	        if (link != null && link.online()) {
   123	            remaining -= (int) link.insertItem(resource, remaining, transaction != null);
   124	        }
   125	        for (ExportBlockEntity block : live()) {
   126	            if (remaining == 0) {
   127	                break;
   128	            }
   129	            remaining -= ResourceHandlerUtil.insertStacking(block.storage(), resource, remaining, transaction);
   130	        }
   131	        return remaining == 0 ? ItemStack.EMPTY : resource.toStack(remaining);
   132	    }
   133	}
