  1	package io.github.julianperge.modular_planters.multiblock;
  2	
  3	import net.neoforged.neoforge.transfer.item.ItemResource;
  4	
  5	public interface MeLink {
  6	    MeStatus status();
  7	
  8	    long insertItem(ItemResource resource, long amount, boolean simulate);
  9	
 10	    long extractItem(ItemResource resource, long amount, boolean simulate);
 11	
 12	    long extractEnergy(long amount, boolean simulate);
 13	
 14	    ItemResource fertilizerFilter();
 15	
 16	    boolean isRemoved();
 17	
 18	    default boolean online() {
 19	        return status() == MeStatus.ONLINE;
 20	    }
 21	}
 22	package io.github.julianperge.modular_planters.gametest;
 23	
 24	import io.github.julianperge.modular_planters.multiblock.MeLink;
 25	import io.github.julianperge.modular_planters.multiblock.MeStatus;
 26	import java.util.HashMap;
 27	import java.util.Map;
 28	import net.neoforged.neoforge.transfer.item.ItemResource;
 29	
 30	public final class FakeMeLink implements MeLink {
 31	    public MeStatus status;
 32	    public boolean removed;
 33	    public ItemResource filter = ItemResource.EMPTY;
 34	    public long energy;
 35	    public long modulateShortfall;
 36	
 37	    private final long capacity;
 38	    private final Map<ItemResource, Long> items = new HashMap<>();
 39	
 40	    public FakeMeLink(MeStatus status, long capacity) {
 41	        this.status = status;
 42	        this.capacity = capacity;
 43	    }
 44	
 45	    public long stored(ItemResource resource) {
 46	        return items.getOrDefault(resource, 0L);
 47	    }
 48	
 49	    public void put(ItemResource resource, long amount) {
 50	        items.merge(resource, amount, Long::sum);
 51	    }
 52	
 53	    @Override
 54	    public MeStatus status() {
 55	        return status;
 56	    }
 57	
 58	    @Override
 59	    public long insertItem(ItemResource resource, long amount, boolean simulate) {
 60	        if (status != MeStatus.ONLINE) {
 61	            return 0;
 62	        }
 63	        long total = items.values().stream().mapToLong(Long::longValue).sum();
 64	        long accepted = Math.min(amount, Math.max(0, capacity - total));
 65	        if (simulate) {
 66	            return accepted;
 67	        }
 68	        long inserted = Math.max(0, accepted - modulateShortfall);
 69	        put(resource, inserted);
 70	        return inserted;
 71	    }
 72	
 73	    @Override
 74	    public long extractItem(ItemResource resource, long amount, boolean simulate) {
 75	        if (status != MeStatus.ONLINE) {
 76	            return 0;
 77	        }
 78	        long extracted = Math.min(amount, stored(resource));
 79	        if (!simulate) {
 80	            items.merge(resource, -extracted, Long::sum);
 81	        }
 82	        return extracted;
 83	    }
 84	
 85	    @Override
 86	    public long extractEnergy(long amount, boolean simulate) {
 87	        if (status != MeStatus.ONLINE) {
 88	            return 0;
 89	        }
 90	        long extracted = Math.min(amount, energy);
 91	        if (!simulate) {
 92	            energy -= extracted;
 93	        }
 94	        return extracted;
 95	    }
 96	
 97	    @Override
 98	    public ItemResource fertilizerFilter() {
 99	        return filter;
100	    }
101	
102	    @Override
103	    public boolean isRemoved() {
104	        return removed;
105	    }
106	}
107	package io.github.julianperge.modular_planters.gametest;
108	
109	import io.github.julianperge.modular_planters.blockentity.ExportBlockEntity;
110	import io.github.julianperge.modular_planters.blockentity.FertilizerBlockEntity;
111	import io.github.julianperge.modular_planters.blockentity.PowerBlockEntity;
112	import io.github.julianperge.modular_planters.multiblock.FertilizerPool;
113	import io.github.julianperge.modular_planters.multiblock.MeStatus;
114	import io.github.julianperge.modular_planters.multiblock.OutputSink;
115	import io.github.julianperge.modular_planters.multiblock.PowerPool;
116	import io.github.julianperge.modular_planters.registry.MPBlocks;
117	import java.util.List;
118	import java.util.Map;
119	import java.util.concurrent.atomic.AtomicBoolean;
120	import net.minecraft.core.BlockPos;
121	import net.minecraft.gametest.framework.GameTestHelper;
122	import net.minecraft.world.item.Item;
123	import net.minecraft.world.item.ItemStack;
124	import net.minecraft.world.item.Items;
125	import net.neoforged.neoforge.transfer.ResourceHandlerUtil;
126	import net.neoforged.neoforge.transfer.item.ItemResource;
127	import net.neoforged.neoforge.transfer.item.ItemStacksResourceHandler;
128	
129	public final class MeLinkTests {
130	    private static final BlockPos EXPORT = new BlockPos(1, 1, 1);
131	
132	    private MeLinkTests() {
133	    }
134	
135	    public static void register(Map<String, TestCase> into) {
136	        into.put("online_link_takes_outputs_first", new TestCase(20, MeLinkTests::onlineLinkTakesOutputsFirst));
137	        into.put("offline_link_sends_outputs_to_export", new TestCase(20, MeLinkTests::offlineLinkSendsOutputsToExport));
138	        into.put("removed_link_is_skipped_and_marks_stale",
139	                new TestCase(20, MeLinkTests::removedLinkIsSkippedAndMarksStale));
140	        into.put("room_counts_me_room", new TestCase(20, MeLinkTests::roomCountsMeRoom));
141	        into.put("me_partial_room_sends_the_rest_to_export",
142	                new TestCase(20, MeLinkTests::mePartialRoomSendsTheRestToExport));
143	        into.put("export_move_puts_contents_into_me", new TestCase(20, MeLinkTests::exportMovePutsContentsIntoMe));
144	        into.put("export_move_conserves_items_when_me_refuses_part",
145	                new TestCase(20, MeLinkTests::exportMoveConservesItemsWhenMeRefusesPart));
146	        into.put("export_move_skips_offline_link", new TestCase(20, MeLinkTests::exportMoveSkipsOfflineLink));
147	        into.put("top_up_fills_fertilizer_from_me", new TestCase(20, MeLinkTests::topUpFillsFertilizerFromMe));
148	        into.put("top_up_ignores_non_fertilizer_filter",
149	                new TestCase(20, MeLinkTests::topUpIgnoresNonFertilizerFilter));
150	        into.put("refill_takes_only_what_was_wanted", new TestCase(20, MeLinkTests::refillTakesOnlyWhatWasWanted));
151	        into.put("refill_is_capped_by_room", new TestCase(20, MeLinkTests::refillIsCappedByRoom));
152	    }
153	
154	    private static ExportBlockEntity placeExport(GameTestHelper helper) {
155	        helper.setBlock(EXPORT, MPBlocks.EXPORT.get());
156	        return helper.getBlockEntity(EXPORT, ExportBlockEntity.class);
157	    }
158	
159	    private static FertilizerBlockEntity placeFertilizer(GameTestHelper helper) {
160	        helper.setBlock(EXPORT, MPBlocks.FERTILIZER.get());
161	        return helper.getBlockEntity(EXPORT, FertilizerBlockEntity.class);
162	    }
163	
164	    private static PowerBlockEntity placePower(GameTestHelper helper) {
165	        helper.setBlock(EXPORT, MPBlocks.POWER.get());
166	        return helper.getBlockEntity(EXPORT, PowerBlockEntity.class);
167	    }
168	
169	    static void fill(ExportBlockEntity export, Item item, int amount) {
170	        ResourceHandlerUtil.insertStacking(export.storage(), ItemResource.of(item), amount, null);
171	    }
172	
173	    static int count(ExportBlockEntity export, Item item) {
174	        ItemStacksResourceHandler storage = export.storage();
175	        int total = 0;
176	        for (int slot = 0; slot < storage.size(); slot++) {
177	            total += storage.getResource(slot).getItem() == item ? storage.getAmountAsInt(slot) : 0;
178	        }
179	        return total;
180	    }
181	
182	    private static void onlineLinkTakesOutputsFirst(GameTestHelper helper) {
183	        ExportBlockEntity export = placeExport(helper);
184	        FakeMeLink me = new FakeMeLink(MeStatus.ONLINE, 1000);
185	        OutputSink sink = new OutputSink(List.of(export), me, () -> {});
186	        helper.assertTrue(sink.insert(new ItemStack(Items.WHEAT, 64)).isEmpty(), "nothing left over");
187	        helper.assertValueEqual(me.stored(ItemResource.of(Items.WHEAT)), 64L, "wheat in ME");
188	        helper.assertValueEqual(count(export, Items.WHEAT), 0, "wheat in export");
189	        helper.succeed();
190	    }
191	
192	    private static void offlineLinkSendsOutputsToExport(GameTestHelper helper) {
193	        ExportBlockEntity export = placeExport(helper);
194	        FakeMeLink me = new FakeMeLink(MeStatus.OFFLINE, 1000);
195	        OutputSink sink = new OutputSink(List.of(export), me, () -> {});
196	        helper.assertTrue(sink.insert(new ItemStack(Items.WHEAT, 64)).isEmpty(), "nothing left over");
197	        helper.assertValueEqual(me.stored(ItemResource.of(Items.WHEAT)), 0L, "wheat in ME");
198	        helper.assertValueEqual(count(export, Items.WHEAT), 64, "wheat in export");
199	        helper.succeed();
200	    }
201	
202	    private static void removedLinkIsSkippedAndMarksStale(GameTestHelper helper) {
203	        ExportBlockEntity export = placeExport(helper);
204	        FakeMeLink me = new FakeMeLink(MeStatus.ONLINE, 1000);
205	        me.removed = true;
206	        AtomicBoolean stale = new AtomicBoolean();
207	        OutputSink sink = new OutputSink(List.of(export), me, () -> stale.set(true));
208	        helper.assertTrue(sink.insert(new ItemStack(Items.WHEAT, 64)).isEmpty(), "nothing left over");
209	        helper.assertValueEqual(me.stored(ItemResource.of(Items.WHEAT)), 0L, "wheat in ME");
210	        helper.assertValueEqual(count(export, Items.WHEAT), 64, "wheat in export");
211	        helper.assertTrue(stale.get(), "onStale ran");
212	        helper.succeed();
213	    }
214	
215	    private static void roomCountsMeRoom(GameTestHelper helper) {
216	        ExportBlockEntity export = placeExport(helper);
217	        int full = ExportBlockEntity.SLOTS * 64;
218	        helper.assertValueEqual(
219	                ResourceHandlerUtil.insertStacking(export.storage(), ItemResource.of(Items.COBBLESTONE), full, null), full,
220	                "pre-filled cobblestone");
221	        FakeMeLink me = new FakeMeLink(MeStatus.ONLINE, 64);
222	        OutputSink sink = new OutputSink(List.of(export), me, () -> {});
223	        helper.assertTrue(sink.hasRoomFor(List.of(new ItemStack(Items.WHEAT, 64))), "ME room counts");
224	        helper.assertTrue(!sink.hasRoomFor(List.of(new ItemStack(Items.WHEAT, 65))), "65 do not fit");
225	        helper.assertValueEqual(me.stored(ItemResource.of(Items.WHEAT)), 0L, "the simulation stored nothing");
226	        helper.succeed();
227	    }
228	
229	    private static void mePartialRoomSendsTheRestToExport(GameTestHelper helper) {
230	        ExportBlockEntity export = placeExport(helper);
231	        FakeMeLink me = new FakeMeLink(MeStatus.ONLINE, 10);
232	        OutputSink sink = new OutputSink(List.of(export), me, () -> {});
233	        List<ItemStack> drops = List.of(new ItemStack(Items.WHEAT, 64), new ItemStack(Items.WHEAT, 64));
234	        helper.assertTrue(sink.hasRoomFor(drops), "room");
235	        for (ItemStack drop : drops) {
236	            helper.assertTrue(sink.insert(drop.copy()).isEmpty(), "nothing left over");
237	        }
238	        helper.assertValueEqual(me.stored(ItemResource.of(Items.WHEAT)), 10L, "wheat in ME");
239	        helper.assertValueEqual(count(export, Items.WHEAT), 118, "wheat in export");
240	        helper.succeed();
241	    }
242	
243	    private static void exportMovePutsContentsIntoMe(GameTestHelper helper) {
244	        ExportBlockEntity export = placeExport(helper);
245	        fill(export, Items.WHEAT, 64);
246	        fill(export, Items.COBBLESTONE, 64);
247	        FakeMeLink me = new FakeMeLink(MeStatus.ONLINE, 1000);
248	        OutputSink sink = new OutputSink(List.of(export), me, () -> {});
249	        sink.moveExportsInto(me);
