 26	import java.util.HashMap;
 27	import java.util.Map;
 28	import net.neoforged.neoforge.transfer.item.ItemResource;
 29	
 30	public final class FakeMeLink implements MeLink {
 31	    public MeStatus status;
 32	    public boolean removed;
 33	    public ItemResource filter = ItemResource.EMPTY;
 34	    public long energy;
 35	    public long modulateShortfall;
 36	
 37	    private final long capacity;
 38	    private final Map<ItemResource, Long> items = new HashMap<>();
 39	
 40	    public FakeMeLink(MeStatus status, long capacity) {
 41	        this.status = status;
 42	        this.capacity = capacity;
 43	    }
 44	
 45	    public long stored(ItemResource resource) {
 46	        return items.getOrDefault(resource, 0L);
 47	    }
 48	
 49	    public void put(ItemResource resource, long amount) {
 50	        items.merge(resource, amount, Long::sum);
 51	    }
 52	
 53	    @Override
 54	    public MeStatus status() {
 55	        return status;
 56	    }
 57	
 58	    @Override
 59	    public long insertItem(ItemResource resource, long amount, boolean simulate) {
 60	        if (status != MeStatus.ONLINE) {
 61	            return 0;
 62	        }
 63	        long total = items.values().stream().mapToLong(Long::longValue).sum();
 64	        long accepted = Math.min(amount, Math.max(0, capacity - total));
 65	        if (simulate) {
 66	            return accepted;
 67	        }
 68	        long inserted = Math.max(0, accepted - modulateShortfall);
 69	        put(resource, inserted);
 70	        return inserted;
 71	    }
 72	
 73	    @Override
 74	    public long extractItem(ItemResource resource, long amount, boolean simulate) {
 75	        if (status != MeStatus.ONLINE) {
 76	            return 0;
 77	        }
 78	        long extracted = Math.min(amount, stored(resource));
 79	        if (!simulate) {
 80	            items.merge(resource, -extracted, Long::sum);
 81	        }
 82	        return extracted;
 83	    }
 84	
 85	    @Override
 86	    public long extractEnergy(long amount, boolean simulate) {
 87	        if (status != MeStatus.ONLINE) {
 88	            return 0;
 89	        }
 90	        long extracted = Math.min(amount, energy);
 91	        if (!simulate) {
 92	            energy -= extracted;
 93	        }
 94	        return extracted;
 95	    }
 96	
 97	    @Override
 98	    public ItemResource fertilizerFilter() {
 99	        return filter;
100	    }
101	
102	    @Override
103	    public boolean isRemoved() {
104	        return removed;
105	    }
106	}
