package io.github.julianperge.modular_planters.ae2;

import appeng.api.config.Actionable;
import appeng.api.networking.security.IActionSource;
import appeng.api.storage.MEStorage;
import com.glodblock.github.appflux.common.me.key.FluxKey;
import com.glodblock.github.appflux.common.me.key.type.EnergyType;

// This is the only class in the mod's main sources that imports Applied Flux (the gated AppliedFluxTests is the other one), and callers reach it only after Ae2Integration.APPLIED_FLUX is true.
final class FluxBridge {
    private FluxBridge() {
    }

    static long extractFe(MEStorage storage, long amount, Actionable mode, IActionSource source) {
        return storage.extract(FluxKey.of(EnergyType.FE), amount, mode, source);
    }
}
    private static void backToCore(ServerPlayer player) {
        if (!(player.containerMenu instanceof PlanterMenu menu) || !menu.fromCore()) {
            return;
        }
        BlockPos anchor = menu.anchor();
        if (player.level().isLoaded(anchor) && player.isWithinBlockInteractionRange(anchor, REACH)
                && player.level().getBlockEntity(anchor) instanceof CoreBlockEntity core) {
            switchMenu(player, () -> open(player, core));
        }
    }

    // Closing a menu puts the cursor stack back into the inventory, so the stack is held out of the old menu and set on the new one, which syncs it to the client on its next broadcast.
    private static void switchMenu(ServerPlayer player, Runnable open) {
        ItemStack carried = player.containerMenu.getCarried();
        player.containerMenu.setCarried(ItemStack.EMPTY);
        open.run();
        player.containerMenu.setCarried(carried);
    }

    @Override
    public void sendAllDataToRemote() {
        super.sendAllDataToRemote();
        sendTable();
    }

    @Override

